"use client";

import { useRef, useState, type ComponentProps } from "react";

import { IconGlobe } from "@rhs-ui/icons";
import { LocalTimePanel } from "@rhs-ui/application/local-time-popover/panel";
import { DEFAULT_LABELS, toTimestamp, triggerText, type LocalTime, type LocalTimeLabels, type LocalZone } from "@rhs-ui/application/local-time-popover/zones";
import { Popover, PopoverContent, PopoverTrigger } from "@rhs-ui/primitives/popover";
import { cn } from "@/lib/utils";

export type { LocalTime, LocalTimeLabels, LocalZone, ZoneRow } from "@rhs-ui/application/local-time-popover/zones";
export { LocalTimePanel, type LocalTimePanelProps } from "@rhs-ui/application/local-time-popover/panel";

export interface LocalTimePopoverProps extends Omit<ComponentProps<"span">, "children" | "title"> {
  /** The moment of the event, as an ISO string with its offset or a "Z": "2026-10-22T16:00:00+02:00". A Date or a timestamp works too. */
  instant: LocalTime;
  /** The zones to show it in, each an IANA name and the name of the place. The viewer's own zone is added at the top if it is not among them. */
  zones: readonly LocalZone[];
  /** The zone the event is in, which the trigger writes the time in and every other zone's day is compared with. Default: the first of `zones`. */
  eventZone?: string;
  /** The viewer's zone. Leave it out to use the browser's own, read once the page is live; nothing here reads the server's zone. */
  viewerZone?: string;
  /** The language of the weekdays, the months and the way a time is written. Default "en-US". */
  locale?: string;
  /** The moment "in 3 days" is measured from. Leave it out to use the browser's clock once the page is live; pass it for the same words in server HTML, in tests and in previews. */
  now?: LocalTime;
  /** The name of the event. It leads the line that Copy as text produces: "Product sync: Thu 22 Oct, 18:00 Amsterdam (UTC+2) / ...". */
  title?: string;
  /** How the trigger writes the time, as `Intl.DateTimeFormat` options. Default: the time and the zone's short name, "18:00 CEST". The zone is always the event's. */
  format?: Intl.DateTimeFormatOptions;
  /** Which edge of the time the list lines up with. Default "start". */
  align?: "start" | "center" | "end";
  /** Whether the list is open, when you control it. */
  open?: boolean;
  /** Whether the list is open to begin with. */
  defaultOpen?: boolean;
  /** Called when the list opens or closes. */
  onOpenChange?: (open: boolean) => void;
  /** The words the popover says, for translation. */
  labels?: LocalTimeLabels;
}

/**
 * An event time that answers "and when is that for me?". The trigger is the time itself, written in the event's zone as a real
 * `time` element with a dotted line under it; pressing it opens the same moment in each zone you chose, the viewer's own zone
 * first and tagged "You", with the day change marked ("Next day") and the distance from UTC in tabular digits. Daylight saving
 * comes from Intl for the actual date, and nothing depends on the server's zone. "Copy as text" puts one line on the clipboard to
 * paste into a chat.
 */
export function LocalTimePopover({
  instant,
  zones,
  eventZone,
  viewerZone,
  locale = "en-US",
  now,
  title,
  format,
  align = "start",
  open,
  defaultOpen = false,
  onOpenChange,
  labels,
  className,
  ...props
}: LocalTimePopoverProps) {
  const words = { ...DEFAULT_LABELS, ...labels };
  const [ownOpen, setOwnOpen] = useState(defaultOpen);
  const content = useRef<HTMLDivElement>(null);
  const isOpen = open ?? ownOpen;
  // A list that is open from the start (a preview, a first-run tip) never takes focus from the page: that is only for a list somebody opened.
  const [wasOpen, setWasOpen] = useState(isOpen);
  const [fresh, setFresh] = useState(isOpen);
  if (isOpen !== wasOpen) {
    setWasOpen(isOpen);
    if (!isOpen) setFresh(false);
  }

  const at = toTimestamp(instant);
  if (Number.isNaN(at)) return null;
  const home = eventZone ?? zones[0]?.id ?? "UTC";

  function setOpen(next: boolean) {
    if (open === undefined) setOwnOpen(next);
    onOpenChange?.(next);
  }

  return (
    <span data-slot="local-time-popover" className={cn("inline-flex", className)} {...props}>
      <Popover open={isOpen} onOpenChange={setOpen}>
        <PopoverTrigger asChild>
          <button
            type="button"
            className="-my-0.5 inline-flex items-baseline gap-1.5 rounded-sm py-0.5 font-medium underline decoration-muted-foreground/60 decoration-dotted underline-offset-4 outline-none transition-colors duration-150 hover:decoration-foreground focus-visible:ring-[3px] focus-visible:ring-ring/40 data-[state=open]:decoration-foreground motion-reduce:transition-none"
          >
            <time dateTime={new Date(at).toISOString()} suppressHydrationWarning className="tabular-nums">
              {triggerText(at, locale, home, format)}
            </time>
            <IconGlobe aria-hidden="true" className="size-3.5 self-center text-muted-foreground" />
            <span className="sr-only">, {words.hint}</span>
          </button>
        </PopoverTrigger>
        <PopoverContent
          ref={content}
          align={align}
          collisionPadding={8}
          aria-label={words.title}
          onOpenAutoFocus={(event) => {
            // Focus goes to the copy button, the one thing in the list to press, unless the list was open from the start.
            event.preventDefault();
            if (fresh) return;
            content.current?.querySelector<HTMLElement>("button")?.focus({ preventScroll: true });
          }}
          // The list scrolls as a whole, copy button included, so the scrolling box always holds something to focus.
          className="relative max-h-[min(34rem,var(--radix-popover-content-available-height))] w-[min(22rem,calc(100vw-1rem))] overflow-y-auto overscroll-contain p-0"
        >
          <LocalTimePanel instant={instant} zones={zones} eventZone={home} viewerZone={viewerZone} locale={locale} now={now} title={title} labels={labels} />
        </PopoverContent>
      </Popover>
    </span>
  );
}

"use client";

import { useEffect, useId, useRef, useState, useSyncExternalStore, type ComponentProps } from "react";

import { IconAlertCircle, IconCheck, IconCopy } from "@rhs-ui/icons";
import {
  browserZone,
  copyLine,
  copyText,
  dayText,
  DEFAULT_LABELS,
  relativeText,
  toTimestamp,
  zoneRows,
  type LocalTime,
  type LocalTimeLabels,
  type LocalZone,
} from "@rhs-ui/application/local-time-popover/zones";
import { Badge } from "@rhs-ui/primitives/badge";
import { Button } from "@rhs-ui/primitives/button";
import { cn } from "@/lib/utils";

export interface LocalTimePanelProps extends Omit<ComponentProps<"div">, "children" | "title"> {
  /** The moment of the event, as an ISO string with its offset or a "Z": "2026-10-22T16:00:00+02:00". A Date or a timestamp works too. */
  instant: LocalTime;
  /** The zones to show it in, each an IANA name and the name of the place. The viewer's own zone is added at the top if it is not among them. */
  zones: readonly LocalZone[];
  /** The zone the event is in: the day in the head of the list is its day, and every other zone's day is compared with it. Default: the first of `zones`. */
  eventZone?: string;
  /** The viewer's zone. Leave it out to use the browser's own, read once the page is live; nothing here reads the server's zone. */
  viewerZone?: string;
  /** The language of the weekdays, the months and the way a time is written. Default "en-US". */
  locale?: string;
  /** The moment "in 3 days" is measured from. Leave it out to use the browser's clock once the page is live; pass it for the same words in server HTML, in tests and in previews. */
  now?: LocalTime;
  /** The name of the event. It leads the line that Copy as text produces: "Product sync: Thu 22 Oct, 18:00 Amsterdam (UTC+2) / ...". */
  title?: string;
  /** The words the panel says, for translation. */
  labels?: LocalTimeLabels;
}

const subscribeNever = (): (() => void) => () => undefined;

/**
 * The inside of the local time popover, on its own, for a sheet on a phone: the day of the event, and under it the same moment in
 * each zone, the viewer's own first and tagged "You", with the day change marked ("Next day") and the distance from UTC in
 * tabular digits. "Copy as text" puts one line on the clipboard to paste into a chat. Daylight saving comes from Intl for the
 * actual date, and nothing depends on the server's zone.
 */
export function LocalTimePanel({ instant, zones, eventZone, viewerZone, locale = "en-US", now, title, labels, className, ...props }: LocalTimePanelProps) {
  const words: Required<LocalTimeLabels> = { ...DEFAULT_LABELS, ...labels };
  const headingId = useId();
  const [status, setStatus] = useState<"idle" | "copied" | "failed">("idle");
  const timer = useRef<number | undefined>(undefined);
  // The browser's own zone and clock are only known in the browser: null on the server and while hydrating, so both write the same list.
  const mounted = useSyncExternalStore(subscribeNever, () => true, () => false);
  const browser = useSyncExternalStore(subscribeNever, () => browserZone(locale), () => null);
  const [tick] = useState(() => Date.now());
  useEffect(() => () => window.clearTimeout(timer.current), []);

  const at = toTimestamp(instant);
  const pinned = now === undefined ? Number.NaN : toTimestamp(now);
  const clock = !Number.isNaN(pinned) ? pinned : mounted ? tick : null;
  const home = eventZone ?? zones[0]?.id ?? "UTC";
  const listed = zones.some((zone) => zone.id === home) ? zones : [{ id: home }, ...zones];
  const rows = Number.isNaN(at) ? [] : zoneRows(at, listed, home, viewerZone ?? browser, locale);
  const relative = clock === null || Number.isNaN(at) ? "" : relativeText(at, clock, locale);

  async function copy() {
    window.clearTimeout(timer.current);
    try {
      await copyText(copyLine(at, rows, home, locale, title));
      setStatus("copied");
    } catch {
      setStatus("failed");
    }
    timer.current = window.setTimeout(() => setStatus("idle"), 2400);
  }

  if (Number.isNaN(at)) return null;

  return (
    <div data-slot="local-time-panel" role="group" aria-labelledby={headingId} className={cn("flex flex-col bg-popover text-popover-foreground", className)} {...props}>
      <div className="grid gap-0.5 px-4 pt-3 pb-3">
        <h2 id={headingId} className="text-sm font-semibold tracking-[-0.01em]">
          {words.title}
        </h2>
        <p className="text-xs text-muted-foreground" suppressHydrationWarning>
          {dayText(at, locale, home)}
          {relative ? <span className="whitespace-nowrap"> · {relative}</span> : null}
        </p>
      </div>
      <ul className="divide-y divide-border border-t border-border">
        {rows.map((row) => (
          <li key={row.id} className="flex items-start justify-between gap-4 px-4 py-2.5">
            <div className="min-w-0">
              <p className="flex min-w-0 items-center gap-2">
                <span className="truncate text-sm font-medium tracking-[-0.01em]">{row.label}</span>
                {row.you ? (
                  <Badge variant="secondary" className="h-[1.125rem] shrink-0 px-1.5 text-[0.6875rem]">
                    {words.you}
                  </Badge>
                ) : null}
              </p>
              <p className="text-xs text-muted-foreground tabular-nums">{row.offset}</p>
            </div>
            <div className="shrink-0 text-right">
              <p className="text-sm font-medium tabular-nums">{row.time}</p>
              {/* On the narrowest phones (the list is then about 300px wide) the day chip drops under the date, so the place name keeps its room. */}
              <p className="flex items-center justify-end gap-1.5 text-xs text-muted-foreground max-[22rem]:flex-col-reverse max-[22rem]:items-end max-[22rem]:gap-0.5">
                {row.shift !== 0 ? (
                  <span className="rounded-sm border border-border px-1 text-[0.6875rem] leading-4 whitespace-nowrap text-foreground">{row.shift > 0 ? words.nextDay : words.previousDay}</span>
                ) : null}
                <span className="whitespace-nowrap">{row.date}</span>
              </p>
            </div>
          </li>
        ))}
      </ul>
      <div className="border-t border-border bg-muted/30 p-1.5">
        {/* Not `disabled` after a press: the button stays focusable, and its words change to say what happened. */}
        <Button type="button" variant="ghost" size="sm" onClick={() => void copy()} className="w-full justify-center text-muted-foreground hover:text-foreground">
          {status === "copied" ? <IconCheck /> : status === "failed" ? <IconAlertCircle /> : <IconCopy />}
          {status === "copied" ? words.copied : status === "failed" ? words.copyFailed : words.copy}
        </Button>
      </div>
      {/* Kept in the page when empty: a live region that appears together with its message is often never read. */}
      <p role="status" aria-live="polite" className="sr-only">
        {status === "copied" ? words.copiedSaid : status === "failed" ? words.copyFailed : ""}
      </p>
    </div>
  );
}

/**
 * The time zone arithmetic and the words behind LocalTimePopover, as plain
 * functions: they hold no state, so a Server Component can use them too. Every
 * one takes the moment and the zones it needs, and every formatter takes the
 * locale, so the server and the browser write the same text for the same
 * moment. Nothing here reads the zone of the machine it runs on, and daylight
 * saving comes from Intl for the actual date.
 */

/** A moment: a Date, an ISO string or a timestamp in milliseconds. */
export type LocalTime = Date | string | number;

/** One zone to show the moment in. */
export interface LocalZone {
  /** The IANA name of the zone, such as "America/Los_Angeles". Daylight saving follows from it. */
  id: string;
  /** What people call the place: "San Francisco". Default: the place in the zone's name. */
  label?: string;
}

/** The words the popover says, for translation. `{time}`, `{title}` and `{count}` are filled in. */
export interface LocalTimeLabels {
  /** The title of the list. Default "Local times". */
  title?: string;
  /** Read after the time on the trigger, so a screen reader knows what it does. Default "show this time in other time zones". */
  hint?: string;
  /** The tag on the viewer's own zone. Default "You". */
  you?: string;
  /** Marks a zone where it is already the next day. Default "Next day". */
  nextDay?: string;
  /** Marks a zone where it is still the day before. Default "Previous day". */
  previousDay?: string;
  /** The button that copies the times as one line. Default "Copy as text". */
  copy?: string;
  /** What the button says once it copied. Default "Copied". */
  copied?: string;
  /** What the button says when the browser refused. Default "Could not copy". */
  copyFailed?: string;
  /** Said once it copied. Default "Copied the times as text." */
  copiedSaid?: string;
}

export const DEFAULT_LABELS = {
  title: "Local times",
  hint: "show this time in other time zones",
  you: "You",
  nextDay: "Next day",
  previousDay: "Previous day",
  copy: "Copy as text",
  copied: "Copied",
  copyFailed: "Could not copy",
  copiedSaid: "Copied the times as text.",
} satisfies Required<LocalTimeLabels>;

/** One line of the list: a zone, and the moment as that zone's clock shows it. */
export interface ZoneRow {
  /** The IANA name of the zone. */
  id: string;
  /** What people call the place. */
  label: string;
  /** The viewer's own zone. */
  you: boolean;
  /** The time of day: "18:00", or "6:00 PM" where the locale counts that way. */
  time: string;
  /** The weekday and the date: "Thu 22 Oct". */
  date: string;
  /** How many days this zone's date is from the event zone's date: -1, 0 or 1 (very rarely 2). */
  shift: number;
  /** The distance from UTC: "UTC+2", "UTC−7", "UTC+5:30". */
  offset: string;
}

/** Puts values into a template: `fill("{title}: {time}", { title, time })`. A name it does not know is left as it was. */
export function fill(template: string, values: Record<string, string>): string {
  return template.replace(/\{(\w+)\}/g, (match, key: string) => (key in values ? (values[key] ?? match) : match));
}

/** A moment as milliseconds, or NaN when it is not a date at all. */
export function toTimestamp(time: LocalTime): number {
  return new Date(time).getTime();
}

const MINUTE = 60_000;
const DAY = 86_400_000;
const HOUR = 3_600_000;

const wallFormats = new Map<string, Intl.DateTimeFormat>();

function wallFormat(timeZone: string): Intl.DateTimeFormat {
  let found = wallFormats.get(timeZone);
  if (!found) {
    try {
      found = new Intl.DateTimeFormat("en-US", { timeZone, hourCycle: "h23", year: "numeric", month: "numeric", day: "numeric", hour: "numeric", minute: "numeric", second: "numeric" });
    } catch {
      // An unknown zone is read as UTC: a typo must not take the page down.
      found = wallFormat("UTC");
    }
    wallFormats.set(timeZone, found);
  }
  return found;
}

/** How far a zone's wall clock is ahead of UTC at a moment, in minutes. */
export function offsetMinutes(at: number, timeZone: string): number {
  const parts = wallFormat(timeZone).formatToParts(at);
  const get = (type: string) => Number(parts.find((part) => part.type === type)?.value);
  return Math.round((Date.UTC(get("year"), get("month") - 1, get("day"), get("hour") % 24, get("minute"), get("second")) - Math.floor(at / 1000) * 1000) / MINUTE);
}

/** The number of the calendar day a moment falls on in a zone, for comparing the days of two zones. */
export function dayNumber(at: number, timeZone: string): number {
  const parts = wallFormat(timeZone).formatToParts(at);
  const get = (type: string) => Number(parts.find((part) => part.type === type)?.value);
  return Math.floor(Date.UTC(get("year"), get("month") - 1, get("day")) / DAY);
}

/** An offset for a glance, with tabular digits in mind: "UTC+2", "UTC−7" with a real minus sign, "UTC+5:30". */
export function offsetText(minutes: number): string {
  const total = Math.abs(minutes);
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  return `UTC${minutes < 0 ? "−" : "+"}${hours}${rest ? `:${String(rest).padStart(2, "0")}` : ""}`;
}

/** "America/Los_Angeles" as "Los Angeles": the place in a zone's name. */
export function cityOf(timeZone: string): string {
  return (timeZone.split("/").pop() ?? timeZone).replace(/_/g, " ");
}

function format(locale: string, timeZone: string, options: Intl.DateTimeFormatOptions, at: number): string {
  let text: string;
  try {
    text = new Intl.DateTimeFormat(locale, { ...options, timeZone }).format(at);
  } catch {
    text = new Intl.DateTimeFormat("en-US", { ...options, timeZone: "UTC" }).format(at);
  }
  // Intl writes some spaces as narrow no-break spaces, and the version of its data decides which: a plain space looks the same and every engine agrees on it.
  return text.replace(/\s/g, " ");
}

/** The way the locale writes a time: 24 hours with two digits where it counts that way ("08:00"), otherwise 12 hours ("8:00 AM"). */
export function clockOptions(locale: string): Intl.DateTimeFormatOptions {
  let cycle: string | undefined;
  try {
    cycle = new Intl.DateTimeFormat(locale, { hour: "numeric" }).resolvedOptions().hourCycle;
  } catch {
    cycle = "h12";
  }
  return cycle === "h23" || cycle === "h24" ? { hour: "2-digit", minute: "2-digit", hourCycle: "h23" } : { hour: "numeric", minute: "2-digit" };
}

/** The moment as the trigger writes it: the time and the zone's short name, "18:00 CEST", unless `options` say otherwise. */
export function triggerText(at: number, locale: string, timeZone: string, options?: Intl.DateTimeFormatOptions): string {
  return format(locale, timeZone, options ?? { ...clockOptions(locale), timeZoneName: "short" }, at);
}

/** The day of the event in words, for the head of the list: "Thursday 22 October 2026". */
export function dayText(at: number, locale: string, timeZone: string): string {
  return format(locale, timeZone, { weekday: "long", day: "numeric", month: "long", year: "numeric" }, at);
}

/** How far off the moment is, in the reader's language: "in 3 days", "tomorrow", "2 hours ago". */
export function relativeText(at: number, now: number, locale: string): string {
  if (Number.isNaN(at)) return "";
  const diff = at - now;
  const [unit, size] = Math.abs(diff) >= DAY ? (["day", DAY] as const) : Math.abs(diff) >= HOUR ? (["hour", HOUR] as const) : (["minute", MINUTE] as const);
  let words: Intl.RelativeTimeFormat;
  try {
    words = new Intl.RelativeTimeFormat(locale, { numeric: "auto" });
  } catch {
    words = new Intl.RelativeTimeFormat("en-US", { numeric: "auto" });
  }
  // From a day up the count is rounded: 47 hours is "in 2 days". Hours and minutes are cut, so 59.6 minutes never reads "in 60 minutes".
  return words.format(unit === "day" ? Math.round(diff / size) : Math.trunc(diff / size), unit);
}

/** The browser's own zone. Only the browser knows it, so call it after the page is live. */
export function browserZone(locale: string): string {
  try {
    return new Intl.DateTimeFormat(locale).resolvedOptions().timeZone;
  } catch {
    return new Intl.DateTimeFormat("en-US").resolvedOptions().timeZone;
  }
}

/**
 * The same moment in every zone, as lines of the list. The viewer's zone comes first and is marked, whether or not it is one of
 * `zones`; the others follow in the order they were given. A zone is listed once, however often it was given.
 */
export function zoneRows(at: number, zones: readonly LocalZone[], eventZone: string, viewerZone: string | null, locale: string): ZoneRow[] {
  const given: LocalZone[] = [];
  for (const zone of zones) if (!given.some((entry) => entry.id === zone.id)) given.push(zone);
  const mine = viewerZone === null ? undefined : (given.find((zone) => zone.id === viewerZone) ?? { id: viewerZone });
  const ordered = mine ? [mine, ...given.filter((zone) => zone.id !== mine.id)] : given;
  const eventDay = dayNumber(at, eventZone);
  return ordered.map((zone) => ({
    id: zone.id,
    label: zone.label ?? cityOf(zone.id),
    you: mine !== undefined && zone.id === mine.id,
    time: format(locale, zone.id, clockOptions(locale), at),
    date: format(locale, zone.id, { weekday: "short", day: "numeric", month: "short" }, at),
    shift: dayNumber(at, zone.id) - eventDay,
    offset: offsetText(offsetMinutes(at, zone.id)),
  }));
}

/** The times as one line to paste into a chat: "Product sync: Thu 22 Oct, 18:00 Amsterdam (UTC+2) / 09:00 San Francisco (UTC−7)". A zone on another day says which. */
export function copyLine(at: number, rows: readonly ZoneRow[], eventZone: string, locale: string, title?: string): string {
  const event = rows.find((row) => row.id === eventZone);
  const segments = [
    ...(event ? [`${format(locale, eventZone, { weekday: "short", day: "numeric", month: "short", ...clockOptions(locale) }, at)} ${event.label} (${event.offset})`] : []),
    ...rows.filter((row) => row.id !== eventZone).map((row) => `${row.shift === 0 ? "" : `${row.date}, `}${row.time} ${row.label} (${row.offset})`),
  ];
  const line = segments.join(" / ");
  return title ? `${title}: ${line}` : line;
}

/**
 * The old way of copying, for pages where the Clipboard API is missing or blocked: the text in a hidden element, selected, and the
 * copy command. The element is selected as a range and never focused, because focus that leaves a popover closes it, and the
 * confirmation would never be seen. What was selected on the page before comes back afterwards.
 */
function legacyCopy(text: string): boolean {
  const holder = document.createElement("span");
  holder.textContent = text;
  Object.assign(holder.style, { position: "fixed", top: "0", left: "0", opacity: "0", pointerEvents: "none", userSelect: "text", whiteSpace: "pre" });
  document.body.append(holder);
  const selection = document.getSelection();
  const before = selection && selection.rangeCount ? selection.getRangeAt(0) : null;
  const range = document.createRange();
  range.selectNodeContents(holder);
  selection?.removeAllRanges();
  selection?.addRange(range);
  let copied = false;
  try {
    copied = document.execCommand("copy");
  } catch {
    copied = false;
  }
  selection?.removeAllRanges();
  if (before) selection?.addRange(before);
  holder.remove();
  return copied;
}

/** Puts text on the clipboard. Rejects when the browser refused. */
export async function copyText(text: string): Promise<void> {
  try {
    await navigator.clipboard.writeText(text);
  } catch (error) {
    if (!legacyCopy(text)) throw error;
  }
}
